<?php
declare(strict_types=1);
namespace EPejabat\Core;
/** Candidate source facts require scoped administrator confirmation; no automatic production seed overwrite. */
final class MasterSourceImport {
 public static function candidates():array {$d=json_decode(file_get_contents(APP_ROOT.'/database/reference/kelantan-candidates.json'),true,512,JSON_THROW_ON_ERROR);$d['organisations']=[...$d['organisations'],...($d['additional_organisation_candidates']??[])];return $d;}
 public static function normalisedName(string $name):string {$name=mb_strtolower(trim($name));$name=preg_replace(['/\Akk\s+/','/\Akd\s+/','/\Akk om\s+/','/\Akkom\s+/','/\Apkd\s+/'],['klinik kesihatan ','klinik desa ','klinik komuniti ','klinik komuniti ','pejabat kesihatan daerah '],$name);return preg_replace('/\s+/',' ',$name);}
 private static function existingAlias(\PDO $p,int $parent,string $name):bool {foreach(Database::query($p,'SELECT name FROM organisations WHERE parent_id=?',[$parent])->fetchAll() as $r)if(self::normalisedName($r['name'])===self::normalisedName($name))return true;return false;}
 public static function apply(\PDO $p,int $actor,array $selected,string $reason,array $parentMapping=[]):array {
  Authorization::require($p,$actor,'core.master.manage');$reason=Core::text($reason,500);$data=self::candidates();$results=[];if(count($selected)>100||count($selected)!==count(array_unique($selected)))throw new \InvalidArgumentException('Pilihan batch tidak sah.');return Core::tx($p,function()use($p,$actor,$selected,$reason,$data,$parentMapping,&$results){
  foreach($selected as $key){$record=null;foreach($data['organisations'] as $r)if($r['local_code']===$key)$record=$r;if(!$record)throw new \InvalidArgumentException('Source candidate tidak sah.');
   $results[]=Core::tx($p,function()use($p,$actor,$record,$reason,$parentMapping){$parent=Database::query($p,'SELECT id FROM organisations WHERE code=? AND is_active=1',[$record['parent_local_code']])->fetchColumn();if(isset($parentMapping[$record['parent_local_code']]))$parent=Core::id($parentMapping[$record['parent_local_code']]);if(isset($parentMapping[$record['local_code']]))$parent=Core::id($parentMapping[$record['local_code']]);if(!$parent)throw new \RuntimeException('Induk perlu disahkan/dipautkan dahulu.');Authorization::require($p,$actor,'core.organisations.manage',(int)$parent);$review=RegistrationMaster::profileReady($p)?Database::query($p,'SELECT * FROM organisation_source_reviews WHERE local_code=?',[$record['local_code']])->fetch():null;if($record['type']!=='pkd'){if(!$review||$review['verification_status']!=='VERIFIED'||(int)$review['parent_id']!==(int)$parent)throw new \RuntimeException('Induk pentadbiran mesti VERIFIED dahulu; lokasi alamat bukan bukti.');$expected=Database::query($p,'SELECT type FROM organisations WHERE id=?',[$parent])->fetchColumn();}else $expected='state';if(!Database::query($p,"SELECT 1 FROM organisations WHERE id=? AND is_active=1 AND (type=? OR (?='facility' AND type='state'))",[$parent,$expected,$record['type']])->fetchColumn())throw new \RuntimeException('Jenis induk tidak sepadan.');
    if(Database::query($p,'SELECT 1 FROM organisations WHERE code=? OR (name=? AND parent_id=?)',[$record['local_code'],$record['name'],$parent])->fetchColumn()||self::existingAlias($p,(int)$parent,$record['name']))return ['code'=>$record['local_code'],'status'=>'SKIPPED_EXISTING_RECONCILIATION_REQUIRED'];
    $type=Database::query($p,"SELECT id FROM master_data WHERE category='organisation_type' AND code=? AND is_active=1",[$record['type']])->fetchColumn();if(!$type)throw new \RuntimeException('Jenis fasiliti perlu disahkan melalui master data.');
    $id=Organisations::save($p,$actor,['code'=>$record['local_code'],'name'=>$record['name'],'type_id'=>$type,'parent_id'=>$parent,'address'=>$record['address']??'','phone'=>$record['phone']??'','reason'=>$reason]);
    if(empty($record['phone']))Database::query($p,'UPDATE organisations SET phone=NULL WHERE id=?',[$id]);
    Database::query($p,"INSERT INTO organisation_directory_details(organisation_id,postcode,district,source_reference,verified_at,verification_status) VALUES(?,?,?,?,?,'ADMIN_CONFIRMED_SOURCE')",[$id,$record['postcode']??null,$record['district']??null,$record['source'],$record['checked_at']]);Database::query($p,'UPDATE organisation_directory_details SET facility_kind=?,phone_source_text=?,phone_validation=? WHERE organisation_id=?',[$record['facility_kind']??null,$record['phone_source_text']??null,$record['phone_validation']??null,$id]);Audit::record($p,'master.source_imported',$actor,(int)$parent,(string)$id,'core',$reason,null,['local_code'=>$record['local_code'],'source'=>$record['source']]);return ['code'=>$record['local_code'],'status'=>'IMPORTED','id'=>$id];
   });
  }return $results;});
 }
 public static function scheme(\PDO $p,int $actor,int $profession,int $position,int $grade,string $source,string $verified,?string $effective=null):void {
  Authorization::require($p,$actor,'core.master.manage');MasterData::validate($p,$profession,'profession');MasterData::validate($p,$position,'position');MasterData::validate($p,$grade,'grade');$u=parse_url($source);if(($u['scheme']??'')!=='https'||!in_array($u['host']??'',['docs.jpa.gov.my','www.moh.gov.my','jknkelantan.moh.gov.my','www.spa.gov.my','spa.gov.my'],true)||isset($u['user'])||isset($u['pass']))throw new \InvalidArgumentException('Gunakan rujukan rasmi.');
  foreach([$verified,$effective] as $date)if($date!==null&&(!preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$date)||strtotime($date)===false||gmdate('Y-m-d',strtotime($date))!==$date||$date>gmdate('Y-m-d')))throw new \InvalidArgumentException('Tarikh tidak sah.');
  Core::tx($p,function()use($p,$actor,$profession,$position,$grade,$source,$verified,$effective){if(Database::query($p,'SELECT 1 FROM master_scheme_grades WHERE profession_id=? AND position_id=? AND grade_id=?',[$profession,$position,$grade])->fetchColumn())throw new \RuntimeException('Padanan wujud; reconciliation diperlukan.');Database::query($p,'INSERT INTO master_scheme_grades(profession_id,position_id,grade_id,source_reference,verified_at,effective_from) VALUES(?,?,?,?,?,?)',[$profession,$position,$grade,$source,$verified,$effective]);Audit::record($p,'master.scheme_grade_verified',$actor,null,(string)$position,'core',null,null,['profession_id'=>$profession,'grade_id'=>$grade,'source'=>$source]);});
 }
 public static function importSchemes(\PDO $p,int $actor,array $selected,string $reason):array {
  Authorization::require($p,$actor,'core.master.manage');$reason=Core::text($reason,500);if(count($selected)>50||count($selected)!==count(array_unique($selected)))throw new \InvalidArgumentException('Pilihan skim tidak sah.');$catalog=self::candidates()['schemes'];$results=[];
  return Core::tx($p,function()use($p,$actor,$selected,$reason,$catalog,&$results){
   foreach($selected as $name){$r=null;foreach($catalog as $c)if($c['name']===$name)$r=$c;if(!$r)throw new \InvalidArgumentException('Skim source tidak sah.');
    $ids=[];foreach(['profession','position'] as $category){$found=Database::query($p,'SELECT id FROM master_data WHERE category=? AND name=?',[$category,$name])->fetchAll();if(count($found)>1)throw new \RuntimeException('Skim duplicate memerlukan reconciliation.');$ids[$category]=$found?(int)$found[0]['id']:MasterData::save($p,$actor,['category'=>$category,'code'=>'SRC_'.substr(hash('sha256',$name),0,24),'name'=>$name]);}
    foreach($r['grades'] as $code){$grade=Database::query($p,"SELECT id FROM master_data WHERE category='grade' AND code=?",[$code])->fetchColumn();if(!$grade)$grade=MasterData::save($p,$actor,['category'=>'grade','code'=>$code,'name'=>$code.' (SSPA)']);
     $exists=Database::query($p,'SELECT 1 FROM master_scheme_grades WHERE profession_id=? AND position_id=? AND grade_id=?',[$ids['profession'],$ids['position'],$grade])->fetchColumn();
     if($exists){$results[]=['scheme'=>$name,'grade'=>$code,'status'=>'SKIPPED_EXISTING'];continue;}
     self::scheme($p,$actor,$ids['profession'],$ids['position'],(int)$grade,$r['source'],$r['checked_at'],$r['effective_from']);
     Database::query($p,'UPDATE master_scheme_grades SET scheme_code=?,ssm_grades_json=?,source_page=? WHERE profession_id=? AND position_id=? AND grade_id=?',[$r['scheme_code'],json_encode($r['ssm_mapping'][$code]??[],JSON_THROW_ON_ERROR),$r['source_page'],$ids['profession'],$ids['position'],$grade]);$results[]=['scheme'=>$name,'grade'=>$code,'status'=>'IMPORTED'];
    }
    Audit::record($p,'master.scheme_source_imported',$actor,null,(string)$ids['position'],'core',$reason,null,['source'=>$r['source']]);
   }return $results;
  });
 }

 public static function reviewOrganisationSource(\PDO $p,int $actor,string $code,int $parent,string $status,string $source,string $reason):void {
  Authorization::require($p,$actor,'core.master.manage');Authorization::require($p,$actor,'core.organisations.manage',$parent);$source=RegistrationMaster::sourceUrl($source);$reason=Core::text($reason,500);$candidate=null;foreach(self::candidates()['organisations'] as $r)if($r['local_code']===$code)$candidate=$r;if(!$candidate||!in_array($status,['VERIFIED','PARTIAL','HOLD','INCOMPLETE','INVALID'],true)||!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$parent])->fetchColumn())throw new \InvalidArgumentException('Rekod/induk/status tidak sah.');
  Core::tx($p,function()use($p,$actor,$code,$parent,$status,$source,$reason){Database::query($p,'INSERT INTO organisation_source_reviews(local_code,parent_id,source_reference,verification_status,reviewed_by,reason) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),source_reference=VALUES(source_reference),verification_status=VALUES(verification_status),reviewed_by=VALUES(reviewed_by),reason=VALUES(reason),reviewed_at=UTC_TIMESTAMP()',[$code,$parent,$source,$status,$actor,$reason]);Audit::record($p,'master.organisation_parent_reviewed',$actor,$parent,$code,'core',$reason,null,['status'=>$status,'parent_id'=>$parent,'source'=>$source]);});
 }
 public static function organisationOfficialName(\PDO $p,int $actor,int $id,string $name,string $source,string $reason):void {
  Authorization::require($p,$actor,'core.organisations.manage',$id);$source=RegistrationMaster::sourceUrl($source);$name=Core::text($name);$reason=Core::text($reason,500);Core::tx($p,function()use($p,$actor,$id,$name,$source,$reason){$r=Database::query($p,'SELECT * FROM organisations WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)throw new \InvalidArgumentException('Organisasi tidak sah.');foreach(Database::query($p,'SELECT id,name FROM organisations WHERE parent_id<=>? AND id<>?',[$r['parent_id'],$id])->fetchAll() as $other)if(self::normalisedName($other['name'])===self::normalisedName($name))throw new \RuntimeException('Nama duplicate; reconciliation diperlukan.');Database::query($p,'INSERT IGNORE INTO organisation_search_aliases(organisation_id,alias) VALUES(?,?)',[$id,$r['name']]);Database::query($p,'UPDATE organisations SET name=? WHERE id=?',[$name,$id]);$after=$r;$after['name']=$name;Database::query($p,'INSERT INTO organisation_change_history(organisation_id,actor_id,reason,before_json,after_json) VALUES(?,?,?,?,?)',[$id,$actor,$reason,json_encode($r,JSON_THROW_ON_ERROR),json_encode($after,JSON_THROW_ON_ERROR)]);Audit::record($p,'organisation.official_name_verified',$actor,$id,(string)$id,'core',$reason,['name'=>$r['name']],['name'=>$name,'source'=>$source]);});
 }
 public static function unitSave(\PDO $p,int $actor,array $d,?int $id=null):int {
  if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_org_',LEFT(SHA2(DATABASE(),256),40)),5)")->fetchColumn()!==1)throw new \RuntimeException('Cuba semula.');try{$parent=Core::id($d['parent_id']??null);Authorization::require($p,$actor,'core.organisations.manage',$parent);RegistrationMaster::sourceUrl($d['source']??'');$name=Core::text($d['name']??'');$rows=Database::query($p,'SELECT id,name FROM organisations WHERE parent_id=?',[$parent])->fetchAll();foreach($rows as $r)if((int)$r['id']!==$id&&self::normalisedName($name)===self::normalisedName($r['name']))throw new \RuntimeException('Unit duplicate.');$type=Database::query($p,"SELECT id FROM master_data WHERE category='organisation_type' AND code='unit' AND is_active=1")->fetchColumn();if(!$type)throw new \RuntimeException('Jenis unit belum tersedia.');if($id){$before=Database::query($p,'SELECT * FROM organisations WHERE id=? AND type=?',[$id,'unit'])->fetch();if(!$before||(int)$before['parent_id']!==$parent)throw new \RuntimeException('Unit/induk tidak sepadan.');$d=array_merge($before,$d);}$d['type_id']=$type;return Organisations::save($p,$actor,$d,$id);}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_org_',LEFT(SHA2(DATABASE(),256),40)))");}
 }

 public static function importProfessionalCatalog(\PDO $p,int $actor,array $selected,string $reason):array {
  Authorization::require($p,$actor,'core.master.manage');$reason=Core::text($reason,500);if(count($selected)>100||count($selected)!==count(array_unique($selected)))throw new \InvalidArgumentException('Batch tidak sah.');$out=[];return Core::tx($p,function()use($p,$actor,$selected,$reason,&$out){foreach($selected as $code){$r=null;foreach(self::candidates()['professional_addenda_candidates']??[] as $candidate)if($candidate['code']===$code)$r=$candidate;if(!$r||$r['verification_status']!=='VERIFIED')throw new \RuntimeException('Hanya data VERIFIED boleh diimport.');$existing=Database::query($p,'SELECT id FROM professional_master_catalog WHERE category=? AND code=?',[$r['category'],$r['code']])->fetchColumn();if($existing){$out[]=['code'=>$code,'status'=>'SKIPPED_EXISTING'];continue;}$id=RegistrationMaster::professionalCatalogSave($p,$actor,['category'=>$r['category'],'code'=>$code,'name'=>$r['name'],'source'=>$r['source'],'reason'=>$reason]);$out[]=['code'=>$code,'id'=>$id,'status'=>'IMPORTED'];}return $out;});
 }

}
